//! Raw FFI bindings to the OpenXR loader, as implemented by Monado.
//!
//! Deliberately minimal but two-faced: the startup probes (enumerate
//! extensions, create an instance, ask for a system) plus the overlay's
//! session path (session, reference space, swapchain, frame loop, quad
//! layer composition). Bindings are generated by hand against the Khronos
//! `openxr.h`; the test module asserts the structure-type discriminators,
//! `XrResult` values, and struct layouts against the values the WinlatorXR
//! tree vendors, so drift fails the build.
//!
//! # ABI notes
//!
//! - Handles (`XrInstance`, `XrSystemId`, `XrSession`, `XrSpace`,
//!   `XrSwapchain`) are `uint64_t`.
//! - `XrVersion` is a packed `uint64_t` per `XR_MAKE_VERSION`:
//!   major at bit 48, minor at bit 32, patch in the low 32 bits.
//! - C enums (`XrResult`, `XrSessionState`, `XrReferenceSpaceType`, …) are
//!   32-bit ints in this ABI; they are alias types plus constants here.
//! - Vulkan handles in the graphics-binding structs are opaque pointers;
//!   ash exposes them via `Handle::as_raw()`.

#![allow(unsafe_code)]
#![allow(clippy::missing_safety_doc)]

use std::os::raw::{c_char, c_void};

/// `XrInstance`, an opaque handle.
pub type XrInstance = u64;
/// `XrSystemId`, an opaque handle.
pub type XrSystemId = u64;
/// `XrSession`, an opaque handle.
pub type XrSession = u64;
/// `XrSpace`, an opaque handle.
pub type XrSpace = u64;
/// `XrSwapchain`, an opaque handle.
pub type XrSwapchain = u64;
/// `XrResult`: 0 is success, positive are successes-with-info, negative errors.
pub type XrResult = i32;
/// `XrStructureType`: discriminator at the head of every OpenXR struct.
pub type XrStructureType = u32;
/// `XrVersion`: packed API version, see `XR_MAKE_VERSION` in the crate docs.
pub type XrVersion = u64;
/// `XrTime` and `XrDuration`: signed 64-bit nanoseconds.
pub type XrTime = i64;
/// See [`XrTime`].
pub type XrDuration = i64;
/// `XrBool32`: 0 is false, anything else true.
pub type XrBool32 = u32;
/// `XrSessionState`, a C enum (32-bit).
pub type XrSessionState = i32;
/// `XrReferenceSpaceType`, a C enum (32-bit).
pub type XrReferenceSpaceType = i32;
/// `XrEnvironmentBlendMode`, a C enum (32-bit).
pub type XrEnvironmentBlendMode = i32;
/// `XrEyeVisibility`, a C enum (32-bit).
pub type XrEyeVisibility = i32;
/// `XrViewConfigurationType`, a C enum (32-bit).
pub type XrViewConfigurationType = i32;
/// `XrFormFactor`, a C enum (32-bit).
pub type XrFormFactor = i32;

/// Opaque `VkInstance`, for the graphics binding; from `ash::vk::Instance`.
pub type VkInstance = *mut c_void;
/// Opaque `VkPhysicalDevice`; from `ash::vk::PhysicalDevice`.
pub type VkPhysicalDevice = *mut c_void;
/// Opaque `VkDevice`; from `ash::vk::Device`.
pub type VkDevice = *mut c_void;
/// Opaque `VkImage`, an acquired swapchain image; from `ash::vk::Image`.
pub type VkImage = *mut c_void;

/// `XR_MAX_EXTENSION_NAME_SIZE` + NUL, per openxr.h.
pub const XR_MAX_EXTENSION_NAME_SIZE: usize = 128;
/// `XR_MAX_APPLICATION_NAME_SIZE` + NUL, per openxr.h.
pub const XR_MAX_APPLICATION_NAME_SIZE: usize = 256;
/// `XR_MAX_ENGINE_NAME_SIZE` + NUL, per openxr.h.
pub const XR_MAX_ENGINE_NAME_SIZE: usize = 64;
/// `XR_MAX_EVENT_DATA_SIZE`: the trailing payload of `XrEventDataBuffer`.
pub const XR_MAX_EVENT_DATA_SIZE: usize = 4000;

// Structure-type discriminators, from the XrStructureType enum in openxr.h.
// The startup-probe discriminators (1-7) and the session-path discriminators
// were re-verified against the Khronos header; the old values this crate
// carried (1/2/4/7 for the probes) did not match openxr.h and are fixed.
/// `XR_TYPE_API_LAYER_PROPERTIES`.
pub const XR_TYPE_API_LAYER_PROPERTIES: XrStructureType = 1;
/// `XR_TYPE_EXTENSION_PROPERTIES`.
pub const XR_TYPE_EXTENSION_PROPERTIES: XrStructureType = 2;
/// `XR_TYPE_INSTANCE_CREATE_INFO`.
pub const XR_TYPE_INSTANCE_CREATE_INFO: XrStructureType = 3;
/// `XR_TYPE_SYSTEM_GET_INFO`.
pub const XR_TYPE_SYSTEM_GET_INFO: XrStructureType = 4;
/// `XR_TYPE_SESSION_CREATE_INFO`.
pub const XR_TYPE_SESSION_CREATE_INFO: XrStructureType = 8;
/// `XR_TYPE_SWAPCHAIN_CREATE_INFO`.
pub const XR_TYPE_SWAPCHAIN_CREATE_INFO: XrStructureType = 9;
/// `XR_TYPE_SESSION_BEGIN_INFO`.
pub const XR_TYPE_SESSION_BEGIN_INFO: XrStructureType = 10;
/// `XR_TYPE_FRAME_END_INFO`.
pub const XR_TYPE_FRAME_END_INFO: XrStructureType = 12;
/// `XR_TYPE_EVENT_DATA_BUFFER`.
pub const XR_TYPE_EVENT_DATA_BUFFER: XrStructureType = 16;
/// `XR_TYPE_EVENT_DATA_INSTANCE_LOSS_PENDING`.
pub const XR_TYPE_EVENT_DATA_INSTANCE_LOSS_PENDING: XrStructureType = 17;
/// `XR_TYPE_EVENT_DATA_SESSION_STATE_CHANGED`.
pub const XR_TYPE_EVENT_DATA_SESSION_STATE_CHANGED: XrStructureType = 18;
/// `XR_TYPE_FRAME_WAIT_INFO`.
pub const XR_TYPE_FRAME_WAIT_INFO: XrStructureType = 33;
/// `XR_TYPE_COMPOSITION_LAYER_QUAD`.
pub const XR_TYPE_COMPOSITION_LAYER_QUAD: XrStructureType = 36;
/// `XR_TYPE_REFERENCE_SPACE_CREATE_INFO`.
pub const XR_TYPE_REFERENCE_SPACE_CREATE_INFO: XrStructureType = 37;
/// `XR_TYPE_FRAME_STATE`.
pub const XR_TYPE_FRAME_STATE: XrStructureType = 44;
/// `XR_TYPE_FRAME_BEGIN_INFO`.
pub const XR_TYPE_FRAME_BEGIN_INFO: XrStructureType = 46;
/// `XR_TYPE_SWAPCHAIN_IMAGE_ACQUIRE_INFO`.
pub const XR_TYPE_SWAPCHAIN_IMAGE_ACQUIRE_INFO: XrStructureType = 55;
/// `XR_TYPE_SWAPCHAIN_IMAGE_WAIT_INFO`.
pub const XR_TYPE_SWAPCHAIN_IMAGE_WAIT_INFO: XrStructureType = 56;
/// `XR_TYPE_SWAPCHAIN_IMAGE_RELEASE_INFO`.
pub const XR_TYPE_SWAPCHAIN_IMAGE_RELEASE_INFO: XrStructureType = 57;
/// `XR_TYPE_GRAPHICS_BINDING_VULKAN_KHR`.
pub const XR_TYPE_GRAPHICS_BINDING_VULKAN_KHR: XrStructureType = 1000025000;
/// `XR_TYPE_SWAPCHAIN_IMAGE_VULKAN_KHR`.
pub const XR_TYPE_SWAPCHAIN_IMAGE_VULKAN_KHR: XrStructureType = 1000025001;

// XrResult codes the wrapper branch on, from the XrResult enum in openxr.h.
/// `XR_SUCCESS`.
pub const XR_SUCCESS: XrResult = 0;
/// `XR_TIMEOUT_EXPIRED`: a wait timed out, not an error.
pub const XR_TIMEOUT_EXPIRED: XrResult = 1;
/// `XR_SESSION_LOSS_PENDING`: returned while a session is being lost.
pub const XR_SESSION_LOSS_PENDING: XrResult = 3;
/// `XR_EVENT_UNAVAILABLE`: no event was pending at poll time.
pub const XR_EVENT_UNAVAILABLE: XrResult = 4;

// XrSessionState, from the XrSessionState enum in openxr.h.
/// `XR_SESSION_STATE_UNKNOWN`.
pub const XR_SESSION_STATE_UNKNOWN: XrSessionState = 0;
/// `XR_SESSION_STATE_IDLE`.
pub const XR_SESSION_STATE_IDLE: XrSessionState = 1;
/// `XR_SESSION_STATE_READY`.
pub const XR_SESSION_STATE_READY: XrSessionState = 2;
/// `XR_SESSION_STATE_SYNCHRONIZED`.
pub const XR_SESSION_STATE_SYNCHRONIZED: XrSessionState = 3;
/// `XR_SESSION_STATE_VISIBLE`.
pub const XR_SESSION_STATE_VISIBLE: XrSessionState = 4;
/// `XR_SESSION_STATE_FOCUSED`.
pub const XR_SESSION_STATE_FOCUSED: XrSessionState = 5;
/// `XR_SESSION_STATE_STOPPING`.
pub const XR_SESSION_STATE_STOPPING: XrSessionState = 6;
/// `XR_SESSION_STATE_LOSS_PENDING`.
pub const XR_SESSION_STATE_LOSS_PENDING: XrSessionState = 7;
/// `XR_SESSION_STATE_EXITING`.
pub const XR_SESSION_STATE_EXITING: XrSessionState = 8;

// XrReferenceSpaceType, from openxr.h.
/// `XR_REFERENCE_SPACE_TYPE_VIEW`.
pub const XR_REFERENCE_SPACE_TYPE_VIEW: XrReferenceSpaceType = 1;
/// `XR_REFERENCE_SPACE_TYPE_LOCAL`.
pub const XR_REFERENCE_SPACE_TYPE_LOCAL: XrReferenceSpaceType = 2;
/// `XR_REFERENCE_SPACE_TYPE_STAGE`.
pub const XR_REFERENCE_SPACE_TYPE_STAGE: XrReferenceSpaceType = 3;

// XrEnvironmentBlendMode, from openxr.h.
/// `XR_ENVIRONMENT_BLEND_MODE_OPAQUE`.
pub const XR_ENVIRONMENT_BLEND_MODE_OPAQUE: XrEnvironmentBlendMode = 1;
/// `XR_ENVIRONMENT_BLEND_MODE_ADDITIVE`.
pub const XR_ENVIRONMENT_BLEND_MODE_ADDITIVE: XrEnvironmentBlendMode = 2;
/// `XR_ENVIRONMENT_BLEND_MODE_ALPHA_BLEND`.
pub const XR_ENVIRONMENT_BLEND_MODE_ALPHA_BLEND: XrEnvironmentBlendMode = 3;

// XrEyeVisibility, from openxr.h.
/// `XR_EYE_VISIBILITY_BOTH`.
pub const XR_EYE_VISIBILITY_BOTH: XrEyeVisibility = 0;

// XrViewConfigurationType, from openxr.h.
/// `XR_VIEW_CONFIGURATION_TYPE_PRIMARY_MONO`.
pub const XR_VIEW_CONFIGURATION_TYPE_PRIMARY_MONO: XrViewConfigurationType = 1;
/// `XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO`.
pub const XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO: XrViewConfigurationType = 2;

/// `XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY`.
pub const XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY: XrFormFactor = 1;

/// `XR_INFINITE_DURATION`: block forever in `xrWaitSwapchainImage`.
pub const XR_INFINITE_DURATION: XrDuration = 0x7FFF_FFFF_FFFF_FFFF;

/// `XR_SWAPCHAIN_USAGE_COLOR_ATTACHMENT_BIT`: the overlay renders into
/// the swapchain; it never reads or samples it back.
pub const XR_SWAPCHAIN_USAGE_COLOR_ATTACHMENT_BIT: u32 = 0x0000_0001;

/// `XrApplicationInfo`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrApplicationInfo {
    /// NUL-padded application name.
    pub application_name: [c_char; XR_MAX_APPLICATION_NAME_SIZE],
    /// NUL-padded engine name.
    pub engine_name: [c_char; XR_MAX_ENGINE_NAME_SIZE],
    /// Developer-defined application version.
    pub application_version: u32,
    /// OpenXR API version, usually `XR_MAKE_VERSION(1, 0, 0)`.
    pub api_version: XrVersion,
}

/// `XrInstanceCreateInfo`.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrInstanceCreateInfo {
    /// Must be `XR_TYPE_INSTANCE_CREATE_INFO`.
    pub type_: XrStructureType,
    /// Next-chain pointer, `XR_NULL` when unused.
    pub next: *const c_void,
    /// Creation flags, 0 for this project.
    pub create_flags: u32,
    /// Embedded application info.
    pub application_info: XrApplicationInfo,
    /// Number of enabled API layers.
    pub enabled_api_layer_count: u32,
    /// Pointers to NUL-terminated layer names.
    pub enabled_api_layer_names: *const *const c_char,
    /// Number of enabled extensions.
    pub enabled_extension_count: u32,
    /// Pointers to NUL-terminated extension names.
    pub enabled_extension_names: *const *const c_char,
}

/// `XrSystemGetInfo`.
