/// `XrEventDataBuffer`: the union every event arrives in. Poll, then read
/// `type_` and cast the trailing bytes to the concrete event struct.
#[repr(C)]
#[derive(Debug, Clone, Copy)]
pub struct XrEventDataBuffer {
    /// Which event arrived; 0 when `XR_EVENT_UNAVAILABLE`.
    pub type_: XrStructureType,
    /// Next-chain pointer, `XR_NULL` when unused.
    pub next: *const c_void,
    /// Trailing payload, [`XR_MAX_EVENT_DATA_SIZE`] bytes.
    pub varying: [u8; XR_MAX_EVENT_DATA_SIZE],
}

#[cfg(feature = "link")]
extern "C" {
    /// Global entry point of the loader; resolves all other functions.
    pub fn xrGetInstanceProcAddr(
        instance: XrInstance,
        name: *const c_char,
        function: *mut *mut c_void,
    ) -> XrResult;

    /// Enumerate the runtime's extensions; two-call pattern.
    pub fn xrEnumerateInstanceExtensionProperties(
        layer: *const c_char,
        count: *mut u32,
        properties: *mut XrExtensionProperties,
    ) -> XrResult;

    /// Create an instance against the active runtime.
    pub fn xrCreateInstance(
        create_info: *const XrInstanceCreateInfo,
        instance: *mut XrInstance,
    ) -> XrResult;

    /// Ask the runtime for a system id for a form factor.
    pub fn xrGetSystem(
        instance: XrInstance,
        get_info: *const XrSystemGetInfo,
        system_id: *mut XrSystemId,
    ) -> XrResult;

    /// Destroy an instance.
    pub fn xrDestroyInstance(instance: XrInstance) -> XrResult;

    /// Poll one event into `event_data`; `XR_EVENT_UNAVAILABLE` when none.
    pub fn xrPollEvent(instance: XrInstance, event_data: *mut XrEventDataBuffer) -> XrResult;

    /// Create a session bound to a graphics device.
    pub fn xrCreateSession(
        instance: XrInstance,
        create_info: *const XrSessionCreateInfo,
        session: *mut XrSession,
    ) -> XrResult;

    /// Destroy a session; all its spaces and swapchains must die first.
    pub fn xrDestroySession(session: XrSession) -> XrResult;

    /// Transition a READY session to RUNNING.
    pub fn xrBeginSession(session: XrSession, begin_info: *const XrSessionBeginInfo) -> XrResult;

    /// Transition a STOPPING session to IDLE.
    pub fn xrEndSession(session: XrSession) -> XrResult;

    /// Ask the runtime to move the session to STOPPING.
    pub fn xrRequestExitSession(session: XrSession) -> XrResult;

    /// Create a reference space (origin pose within LOCAL/STAGE/…).
    pub fn xrCreateReferenceSpace(
        session: XrSession,
        create_info: *const XrReferenceSpaceCreateInfo,
        space: *mut XrSpace,
    ) -> XrResult;

    /// Destroy a space.
    pub fn xrDestroySpace(space: XrSpace) -> XrResult;

    /// Enumerate the session's supported swapchain formats (VkFormat
    /// values as int64); two-call pattern.
    pub fn xrEnumerateSwapchainFormats(
        session: XrSession,
        format_capacity_input: u32,
        format_count_output: *mut u32,
        formats: *mut i64,
    ) -> XrResult;

    /// Create a swapchain.
    pub fn xrCreateSwapchain(
        session: XrSession,
        create_info: *const XrSwapchainCreateInfo,
        swapchain: *mut XrSwapchain,
    ) -> XrResult;

    /// Destroy a swapchain.
    pub fn xrDestroySwapchain(swapchain: XrSwapchain) -> XrResult;

    /// Enumerate the `VkImage`s behind a swapchain; two-call pattern.
    pub fn xrEnumerateSwapchainImages(
        swapchain: XrSwapchain,
        image_capacity_input: u32,
        image_count_output: *mut u32,
        images: *mut XrSwapchainImageVulkanKHR,
    ) -> XrResult;

    /// Acquire the next image index for writing.
    pub fn xrAcquireSwapchainImage(
        swapchain: XrSwapchain,
        acquire_info: *const XrSwapchainImageAcquireInfo,
        index: *mut u32,
    ) -> XrResult;

    /// Block until the acquired image is usable; timeout may expire.
    pub fn xrWaitSwapchainImage(
        swapchain: XrSwapchain,
        wait_info: *const XrSwapchainImageWaitInfo,
    ) -> XrResult;

    /// Release the acquired image to the compositor.
    pub fn xrReleaseSwapchainImage(
        swapchain: XrSwapchain,
        release_info: *const XrSwapchainImageReleaseInfo,
    ) -> XrResult;

    /// Block until the next frame's timing is known.
    pub fn xrWaitFrame(
        session: XrSession,
        frame_wait_info: *const XrFrameWaitInfo,
        frame_state: *mut XrFrameState,
    ) -> XrResult;

    /// Open the frame; rendering may start.
    pub fn xrBeginFrame(session: XrSession, frame_begin_info: *const XrFrameBeginInfo) -> XrResult;

    /// Submit the frame's composition layers.
    pub fn xrEndFrame(session: XrSession, frame_end_info: *const XrFrameEndInfo) -> XrResult;
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn structure_type_constants_match_openxr_h() {
        // From the XrStructureType enum in the Khronos openxr.h vendored by
        // the WinlatorXR tree. If this fails after an SDK bump, re-check.
        assert_eq!(XR_TYPE_API_LAYER_PROPERTIES, 1);
        assert_eq!(XR_TYPE_EXTENSION_PROPERTIES, 2);
        assert_eq!(XR_TYPE_INSTANCE_CREATE_INFO, 3);
        assert_eq!(XR_TYPE_SYSTEM_GET_INFO, 4);
        assert_eq!(XR_TYPE_SESSION_CREATE_INFO, 8);
        assert_eq!(XR_TYPE_SWAPCHAIN_CREATE_INFO, 9);
        assert_eq!(XR_TYPE_SESSION_BEGIN_INFO, 10);
        assert_eq!(XR_TYPE_FRAME_END_INFO, 12);
        assert_eq!(XR_TYPE_EVENT_DATA_BUFFER, 16);
        assert_eq!(XR_TYPE_EVENT_DATA_INSTANCE_LOSS_PENDING, 17);
        assert_eq!(XR_TYPE_EVENT_DATA_SESSION_STATE_CHANGED, 18);
        assert_eq!(XR_TYPE_FRAME_WAIT_INFO, 33);
        assert_eq!(XR_TYPE_COMPOSITION_LAYER_QUAD, 36);
        assert_eq!(XR_TYPE_REFERENCE_SPACE_CREATE_INFO, 37);
        assert_eq!(XR_TYPE_FRAME_STATE, 44);
        assert_eq!(XR_TYPE_FRAME_BEGIN_INFO, 46);
        assert_eq!(XR_TYPE_SWAPCHAIN_IMAGE_ACQUIRE_INFO, 55);
        assert_eq!(XR_TYPE_SWAPCHAIN_IMAGE_WAIT_INFO, 56);
        assert_eq!(XR_TYPE_SWAPCHAIN_IMAGE_RELEASE_INFO, 57);
        assert_eq!(XR_TYPE_GRAPHICS_BINDING_VULKAN_KHR, 1000025000);
        assert_eq!(XR_TYPE_SWAPCHAIN_IMAGE_VULKAN_KHR, 1000025001);
    }

    #[test]
    fn result_codes_match_openxr_h() {
        assert_eq!(XR_SUCCESS, 0);
        assert_eq!(XR_TIMEOUT_EXPIRED, 1);
        assert_eq!(XR_SESSION_LOSS_PENDING, 3);
        assert_eq!(XR_EVENT_UNAVAILABLE, 4);
        assert_eq!(XR_INFINITE_DURATION, i64::MAX);
        assert_eq!(XR_SWAPCHAIN_USAGE_COLOR_ATTACHMENT_BIT, 1);
    }

    #[test]
    fn session_states_match_openxr_h() {
        assert_eq!(XR_SESSION_STATE_UNKNOWN, 0);
        assert_eq!(XR_SESSION_STATE_IDLE, 1);
        assert_eq!(XR_SESSION_STATE_READY, 2);
        assert_eq!(XR_SESSION_STATE_SYNCHRONIZED, 3);
        assert_eq!(XR_SESSION_STATE_VISIBLE, 4);
        assert_eq!(XR_SESSION_STATE_FOCUSED, 5);
        assert_eq!(XR_SESSION_STATE_STOPPING, 6);
        assert_eq!(XR_SESSION_STATE_LOSS_PENDING, 7);
        assert_eq!(XR_SESSION_STATE_EXITING, 8);
    }

    #[test]
    fn enums_are_32_bit_like_c() {
        assert_eq!(std::mem::size_of::<XrFormFactor>(), 4);
        assert_eq!(std::mem::size_of::<XrSessionState>(), 4);
        assert_eq!(std::mem::size_of::<XrReferenceSpaceType>(), 4);
        assert_eq!(std::mem::size_of::<XrEnvironmentBlendMode>(), 4);
        assert_eq!(std::mem::size_of::<XrEyeVisibility>(), 4);
        assert_eq!(std::mem::size_of::<XrViewConfigurationType>(), 4);
        assert_eq!(XR_FORM_FACTOR_HEAD_MOUNTED_DISPLAY, 1);
        assert_eq!(XR_REFERENCE_SPACE_TYPE_VIEW, 1);
        assert_eq!(XR_REFERENCE_SPACE_TYPE_LOCAL, 2);
        assert_eq!(XR_REFERENCE_SPACE_TYPE_STAGE, 3);
        assert_eq!(XR_ENVIRONMENT_BLEND_MODE_OPAQUE, 1);
        assert_eq!(XR_ENVIRONMENT_BLEND_MODE_ALPHA_BLEND, 3);
        assert_eq!(XR_EYE_VISIBILITY_BOTH, 0);
        assert_eq!(XR_VIEW_CONFIGURATION_TYPE_PRIMARY_STEREO, 2);
    }

    #[test]
    fn application_info_size_matches_c() {
        // XrApplicationInfo: 256 + 64 + 4 (+4 pad) + 8 = 336 bytes.
        assert_eq!(std::mem::size_of::<XrApplicationInfo>(), 336);
    }

    #[test]
    fn instance_create_info_has_no_hidden_padding() {
        // type/pad + next + flags/pad + appinfo + layercount/pad + ptr +
        // extcount/pad + ptr = 16 + 8 + 336 + 8 + 8 + 8 + 8 = 392.
        assert_eq!(std::mem::size_of::<XrInstanceCreateInfo>(), 392);
    }

    #[test]
    fn probe_and_session_structs_match_c_layout() {
        assert_eq!(std::mem::size_of::<XrSystemGetInfo>(), 24);
        assert_eq!(std::mem::size_of::<XrExtensionProperties>(), 152);
        assert_eq!(std::mem::size_of::<XrQuaternionf>(), 16);
        assert_eq!(std::mem::size_of::<XrVector3f>(), 12);
        assert_eq!(std::mem::size_of::<XrPosef>(), 28);
        assert_eq!(std::mem::size_of::<XrOffset2Di>(), 8);
        assert_eq!(std::mem::size_of::<XrExtent2Di>(), 8);
        assert_eq!(std::mem::size_of::<XrRect2Di>(), 16);
        assert_eq!(std::mem::size_of::<XrExtent2Df>(), 8);
    }

    #[test]
    fn session_path_structs_match_c_layout() {
        // Each assert is the layout computed from the openxr.h field order
        // on a 64-bit ABI: pointer/8-byte fields align to 8, u32 pairs pack.
        assert_eq!(std::mem::size_of::<XrSessionCreateInfo>(), 32);
        assert_eq!(std::mem::size_of::<XrGraphicsBindingVulkanKHR>(), 48);
        assert_eq!(std::mem::size_of::<XrReferenceSpaceCreateInfo>(), 48);
        assert_eq!(std::mem::size_of::<XrSwapchainCreateInfo>(), 56);
        assert_eq!(std::mem::size_of::<XrSwapchainImageVulkanKHR>(), 24);
        assert_eq!(std::mem::size_of::<XrSwapchainSubImage>(), 32);
        assert_eq!(std::mem::size_of::<XrCompositionLayerQuad>(), 112);
        assert_eq!(std::mem::size_of::<XrFrameWaitInfo>(), 16);
        assert_eq!(std::mem::size_of::<XrFrameState>(), 40);
        assert_eq!(std::mem::size_of::<XrFrameBeginInfo>(), 16);
        assert_eq!(std::mem::size_of::<XrFrameEndInfo>(), 40);
        assert_eq!(std::mem::size_of::<XrSessionBeginInfo>(), 24);
        assert_eq!(std::mem::size_of::<XrSwapchainImageAcquireInfo>(), 16);
        assert_eq!(std::mem::size_of::<XrSwapchainImageWaitInfo>(), 24);
        assert_eq!(std::mem::size_of::<XrSwapchainImageReleaseInfo>(), 16);
        assert_eq!(std::mem::size_of::<XrEventDataSessionStateChanged>(), 40);
        assert_eq!(std::mem::size_of::<XrEventDataBuffer>(), 4016);
    }
}
